do      -- every object made by this screen carries _lookScope = L.id (Look.Id(obj) = "<screen>:<node id>")
    local function scoped(fn) return function(...) return Look.InScope(L.id, fn, ...) end end
    L.build = scoped(L.build)
    L.sample = scoped(L.sample)
    for k, t in pairs(L.templates) do L.templates[k] = scoped(t) end
end
L.shell = { type = "window", frame = "SpokenWindFartLog", strata = "HIGH", toplevel = true, clamp = true, movable = true, esc = true, resize = false }
L.open = function(refs, owner)      -- host: after L.build + L.sample; owner = the owner screen's root frame
    Look.Shell(refs.root, refs, L.shell)
    if L.shell.dock then
        Look.Dock(refs.root, L.shell)
    elseif owner and (L.shell.anchor or L.shell.type == "dialog") then
        Look.Place(refs.root, owner, L.shell)
    end
    Look.Restore(refs.root, refs, L.shell)      -- wave3-e: the stored size and place
end

